# Ausführliche Erklärtexte für den Bereich „Wissen“ (kommen direkt aus der App, YouTube nur als Zusatz).
# ERGAENZUNG: Titel → zusätzliche/ersetzende Felder für bestehende Wissen-Einträge.
#   problem   = Worum geht's / wo liegt die Schwierigkeit
#   text      = ausführliche Erklärung (ersetzt den kurzen Text)
#   fehler    = typische Fehler
#   stichworte= Regex-Muster: passt eine Übungsfrage dazu, zeigt das Quiz „Ausführlich erklärt“
# NEU: (kind, fach) → zusätzliche Wissen-Einträge für Fächer ohne Erklärungen.

def W(titel, kurz, problem, text, schritte=None, beispiel=None, fehler=None, merke=None, video=None, stichworte=None):
    d = {"titel": titel, "kurz": kurz, "problem": problem, "text": text}
    for k, v in [("schritte", schritte), ("beispiel", beispiel), ("fehler", fehler), ("merke", merke), ("video", video), ("stichworte", stichworte)]:
        if v: d[k] = v
    return d

